 check('Eleven distinct mechanical procedures/four untouched receipts',len(P)==len(selected)==11 and len({x['spellId'] for x in P})==11 and {x['spellId'] for x in P}==set(selected) and len(deferred)==4)
 check('848catalog identities with412reviewed/436pending unchanged',len(catalog)==848 and idx['authoredCounts']=={'reviewed':412,'pending':436})
