 for label,actual,expected in arithmetic:check(label,actual==expected)
 source_info={p.relative_to(G).as_posix():info(p) for p in sorted(inputs)};now=datetime.now(timezone.utc).isoformat()
 save(draft,{'status':SHARED['status'],'createdAtUtc':now,'sharedProposal':SHARED,'proposals':P,'explicitJointIssues':ISSUES})
